sp_widget.client_script:
api.controller = function ($scope, $location) {
  /* widget controller */
  var c = this;

  $scope.handleClick = function (hackathon_id) {
    // Handle click event
    // window.location.href =
    //   "/hck?id=ticket&sys_id=" +
    //   hackathon_id +
    //   "&table=x_1097288_hacktaho_hackathon_registration";
    // // You can add more logic here, like navigating to a different page or opening a modal

    if ($scope.data.hasRole) {
      $location.url(
        "/hck?id=team_registration&sys_id=-1&table=x_1097288_hacktaho_hackathon_team&view=hck&hackathon_id=" +
          hackathon_id
      ); // redirect non-role users
    } else {
      $location.url(
        "/hck?id=sn_user_registration&sys_id=d90cf454c33bea10a4e87205e40131a3"
      ); // redirect role users
    }
  };
};

sp_widget.css:
.hck-header-h3-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 16px;
}

.hck-header-h3-container {
  .hck-btn-join-now {
    background-color: #d32f2f;
    color: white;
    border: none;
    border-radius: 4px;
    padding: 8px 16px;
    font-size: 16px;
    cursor: pointer;
    transition: background-color 0.3s;
  }
}

.hck-header-h3 {
  padding: 16px;
}

sp_widget.script:
(function () {
  /* populate the 'data' object */
  /* e.g., data.table = $sp.getValue('table'); */

  var hackathonSysId = $sp.getParameter("sys_id");
  data.hasRole = gs.hasRole("snc_external");
  data.hackathonSysId = hackathonSysId;
  var gr = new GlideRecord("x_1097288_hacktaho_hackathon_registration");
  if (gr.get(hackathonSysId)) {
    data.title = gr.getValue("hackathon_name");
  } else {
    data.title = "No Title Found";
  }
})();
